package com.franco.desco.adapter.in.web.census;import com.franco.desco.application.census.CensusCommands;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.census.CensusModels;import org.springframework.stereotype.Component;import java.time.LocalDate;@Component public class CensusWebMapper{public CensusCommands.ListCensuses list(int p,int s,Long cultivoId,Long parcelaId,LocalDate desde,LocalDate hasta){return new CensusCommands.ListCensuses(new PageRequest<>(p,s,new CensusCommands.Filter(cultivoId,parcelaId,desde,hasta),null,null));}public CensusCommands.CreateCensus command(CensusRequests.Create r){return new CensusCommands.CreateCensus(r.parcelaCultivoId(),r.fechaCenso(),r.plantasTotales(),r.plantasProductivas(),r.plantasNoProductivas(),r.plantasNuevas(),r.plantasMuertas(),r.plantasAfectadas(),r.observacion());}public CensusCommands.UpdateCensus command(Long id,CensusRequests.Update r){return new CensusCommands.UpdateCensus(id,r.parcelaCultivoId(),r.fechaCenso(),r.plantasTotales(),r.plantasProductivas(),r.plantasNoProductivas(),r.plantasNuevas(),r.plantasMuertas(),r.plantasAfectadas(),r.observacion());}public CensusResponses.Summary response(CensusModels.Summary v){return new CensusResponses.Summary(v.censoPlantasId(),v.parcelaCultivoId(),v.parcelaId(),v.parcelaCodigo(),v.parcelaNombre(),v.variedad(),v.fechaCenso(),v.plantasTotales(),v.plantasProductivas(),v.plantasNoProductivas(),v.plantasNuevas(),v.plantasMuertas(),v.plantasAfectadas(),v.observacion(),v.estado());}}
